// Generic fallback — a tinted rounded dot with an initial. Used when a
// satellite doesn't match any of the branded icons above.
export function LetterIcon({
  letter,
  color,
  ...props
}: IconProps & { letter: string; color?: string }) {
  return (
    <svg viewBox="0 0 24 24" {...props}>
      <rect width="24" height="24" rx="6" fill={color || '#0a0a0a'} />
      <text
        x="12"
        y="16"
        textAnchor="middle"
        fontSize="12"
        fontWeight="700"
        fill="white"
        fontFamily="system-ui, sans-serif"
      >
        {letter}
      </text>
    </svg>
  );
}
